CREATE TABLE IF NOT EXISTS gis_dataset_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES gis_authoritative_sources(id) ON DELETE CASCADE, resource_key text NOT NULL UNIQUE, resource_name text NOT NULL, resource_url text NOT NULL, resource_type text NOT NULL DEFAULT 'UNKNOWN', discovery_status text NOT NULL DEFAULT 'DISCOVERED', authority_status text NOT NULL DEFAULT 'UNVERIFIED', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());